/**
 * The scene the pet lives in: sky by time of day, clouds and precipitation from the real weather,
 * ground, pet, items, particles and a status line with the time and temperature. While the pet is
 * on a trip, the scene shows the landscape it is hopping through instead of its home. A wild pet
 * it has made friends with shows up in both: on the trip where they meet, and at home when it
 * comes to visit.
 *
 * Everything here is presentation only: where the pet hops or when it blinks is up to the
 * renderer; what it does and how it feels comes from the game logic (Pet.view()). That goes for a
 * scuffle on a trip too: it has long been decided when the panel plays its rounds back.
 *
 * The pixel art lives in app/pet/assets/ as sprite sheets (generated by
 * tools/build_blob_sprites.py): body poses and faces are separate, and the face is placed onto
 * every body frame.
 */

