      const f = this.facing;
      pose.body = p < 0.1 || p > 0.85 ? "idle" : p < 0.25 || p > 0.68 ? "squash" : "flat";
      pose.face = p >= 0.25 && p <= 0.68 ? "blink" : p > 0.72 ? "laugh" : "smile";
      if (p > 0.72 && p < 0.85) {
        pose.body = "stretch"; // chest out
      }
