        const speed = ACCOLADE_RUN / (0.22 * TRICK_SHOW);
        this.trickFx(t, "accolade_shine", TRICK_SHOW, NEEDLE_SHINE, 1, 10 * f, dy + 1, [0, 0], [speed, speed], 0.22 * TRICK_SHOW);
