        const spiral = (at: number): [number, number] => {
          const [a, r] = [at * 2 * (2 * Math.PI), 5 + Math.sin(at * Math.PI) * 19];
          return [this.x + SPRITE / 2 + Math.cos(a) * r, GROUND - 13 + Math.sin(a) * r * 0.55];
        };
