      pose.body = p < 0.1 || p > 0.85 ? "idle" : p < 0.22 || p > 0.72 ? "squash" : "flat";
      pose.face = p >= 0.22 && p <= 0.72 ? "blink" : p > 0.72 ? "laugh" : "smile";
      const up = Math.sin(clamp((p - 0.24) / 0.46, 0, 1) * Math.PI);
