      const lean = Math.sin(clamp((p - 0.1) / 0.72, 0, 1) * Math.PI);
      Object.assign(pose, { rotate: -20 * lean * this.facing, face: lean > 0.6 ? "blink" : p > 0.75 ? "laugh" : "smile" });
