      const nod = p > 0.3 && p < 0.74 ? Math.max(0, Math.sin((p - 0.3) / 0.44 * 2 * (2 * Math.PI))) : 0;
      Object.assign(pose, { body: nod > 0.3 ? "squash" : "idle", face: pose.fold === 1 ? (nod > 0.3 ? "blink" : "smile") : "happy" });
